import { GoPanic } from "@gotots/runtime/panic.js";
import { RuntimeSlice } from "@gotots/runtime/slice.js";
import { hostInteger } from "../../host-integer.js";
import { readElement, storedValues, storeElement, } from "./capabilities.js";
import { allocateSlice, clearTail, growthCapacity, validateRange, } from "./storage.js";
export function Clip(source) {
    return source.slice(0, source.length, source.length);
}
export function Clone(toSlice, fromSlice, copyElement, fromStorage, toStorage, source) {
    const values = toSlice(source);
    return values.isNil()
        ? source
        : fromSlice(RuntimeSlice.literal(storedValues(values, copyElement, fromStorage, toStorage)));
}
export function Compact(toSlice, fromSlice, copyElement, equal, fromStorage, toStorage, zeroElement, source) {
    const values = toSlice(source);
    return compact(fromSlice, copyElement, equal, fromStorage, toStorage, zeroElement, source, values);
}
export function CompactFunc(toSlice, fromSlice, copyElement, fromStorage, toStorage, zeroElement, source, equal) {
    const values = toSlice(source);
    if (values.length < 2) {
        return source;
    }
    if (equal === undefined) {
        GoPanic.raiseRuntime("invalid memory address or nil pointer dereference");
    }
    return compact(fromSlice, copyElement, equal, fromStorage, toStorage, zeroElement, source, values);
}
export function Concat(toSlice, fromSlice, copyElement, fromStorage, toStorage, zeroElement, sources) {
    let size = 0;
    for (let sourceIndex = 0; sourceIndex < sources.length; sourceIndex += 1) {
        size += toSlice(sources.get(sourceIndex)).length;
        if (!Number.isSafeInteger(size)) {
            GoPanic.raiseRuntime("len out of range");
        }
    }
    if (size === 0) {
        return fromSlice(RuntimeSlice.nil());
    }
    const result = allocateSlice(size, growthCapacity(0, size), toStorage, zeroElement);
    let write = 0;
    for (let sourceIndex = 0; sourceIndex < sources.length; sourceIndex += 1) {
        const source = toSlice(sources.get(sourceIndex));
        for (let read = 0; read < source.length; read += 1) {
            storeElement(result, write, readElement(source, read, copyElement, fromStorage), copyElement, toStorage);
            write += 1;
        }
    }
    return fromSlice(result);
}
export function Delete(toSlice, fromSlice, copyElement, fromStorage, toStorage, zeroElement, source, start, end) {
    const values = toSlice(source);
    const startIndex = hostInteger(start);
    const endIndex = hostInteger(end);
    validateRange(values.length, startIndex, endIndex);
    if (start === end) {
        return source;
    }
    const removed = endIndex - startIndex;
    for (let read = endIndex; read < values.length; read += 1) {
        storeElement(values, read - removed, readElement(values, read, copyElement, fromStorage), copyElement, toStorage);
    }
    const nextLength = values.length - removed;
    clearTail(values, nextLength, copyElement, toStorage, zeroElement);
    return fromSlice(values.slice(0, nextLength, null));
}
export function DeleteFunc(toSlice, fromSlice, copyElement, fromStorage, toStorage, zeroElement, source, predicate) {
    if (predicate === undefined) {
        GoPanic.raiseRuntime("invalid memory address or nil pointer dereference");
    }
    const values = toSlice(source);
    let write = 0;
    for (let read = 0; read < values.length; read += 1) {
        const value = fromStorage(values.get(read));
        if (!predicate(value)) {
            storeElement(values, write, value, copyElement, toStorage);
            write += 1;
        }
    }
    for (let index = write; index < values.length; index += 1) {
        storeElement(values, index, zeroElement(), copyElement, toStorage);
    }
    return fromSlice(values.slice(0, write, null));
}
export function Grow(toSlice, fromSlice, copyElement, fromStorage, toStorage, zeroElement, source, amount) {
    const values = toSlice(source);
    if (amount < 0n) {
        GoPanic.raiseRuntime("cannot be negative");
    }
    const numericAmount = hostInteger(amount);
    const requiredCapacity = values.length + numericAmount;
    if (!Number.isSafeInteger(requiredCapacity)) {
        GoPanic.raiseRuntime("cannot be negative");
    }
    if (requiredCapacity <= values.capacity) {
        return source;
    }
    let nextCapacity = values.capacity === 0 ? 1 : values.capacity * 2;
    while (nextCapacity < requiredCapacity) {
        nextCapacity *= 2;
    }
    if (!Number.isSafeInteger(nextCapacity)) {
        GoPanic.raiseRuntime("cannot be negative");
    }
    const result = RuntimeSlice.make(nextCapacity, nextCapacity, toStorage(zeroElement()));
    for (let index = 0; index < nextCapacity; index += 1) {
        result.set(index, toStorage(zeroElement()));
    }
    for (let index = 0; index < values.length; index += 1) {
        storeElement(result, index, fromStorage(values.get(index)), copyElement, toStorage);
    }
    return fromSlice(result.slice(0, values.length, null));
}
export function Repeat(toSlice, fromSlice, copyElement, fromStorage, toStorage, source, count) {
    if (count < 0n) {
        GoPanic.raiseRuntime("cannot be negative");
    }
    const hostCount = hostInteger(count);
    const values = toSlice(source);
    const resultLength = values.length * hostCount;
    if (!Number.isSafeInteger(resultLength)) {
        GoPanic.raiseRuntime("the result of (len(x) * count) overflows");
    }
    const result = [];
    for (let repetition = 0; repetition < hostCount; repetition += 1) {
        result.push(...storedValues(values, copyElement, fromStorage, toStorage));
    }
    return fromSlice(RuntimeSlice.literal(result));
}
export function Reverse(toSlice, copyElement, fromStorage, toStorage, source) {
    const values = toSlice(source);
    for (let left = 0, right = values.length - 1; left < right; left += 1, right -= 1) {
        const leftValue = readElement(values, left, copyElement, fromStorage);
        const rightValue = readElement(values, right, copyElement, fromStorage);
        storeElement(values, left, rightValue, copyElement, toStorage);
        storeElement(values, right, leftValue, copyElement, toStorage);
    }
}
function compact(fromSlice, copyElement, equal, fromStorage, toStorage, zeroElement, source, values) {
    if (values.length < 2) {
        return source;
    }
    for (let duplicate = 1; duplicate < values.length; duplicate += 1) {
        if (equal(readElement(values, duplicate, copyElement, fromStorage), readElement(values, duplicate - 1, copyElement, fromStorage))) {
            let write = duplicate;
            for (let read = duplicate + 1; read < values.length; read += 1) {
                if (!equal(readElement(values, read, copyElement, fromStorage), readElement(values, read - 1, copyElement, fromStorage))) {
                    storeElement(values, write, readElement(values, read, copyElement, fromStorage), copyElement, toStorage);
                    write += 1;
                }
            }
            clearTail(values, write, copyElement, toStorage, zeroElement);
            return fromSlice(values.slice(0, write, null));
        }
    }
    return source;
}
